# Security headers on EVERY API response.
#
# A middleware rather than `config.action_dispatch.default_headers` because that only covers controller responses: those
# generated by other middlewares before reaching Rails (ApiRequestGuard, Rack::Attack, HostAuthorization) would go out
# without them. It sits FIRST in the stack and writes on the way back, so it overrides laxer values (Rails sets
# `X-Frame-Options: SAMEORIGIN`).
#
#   X-Content-Type-Options  nosniff
#   Referrer-Policy         strict-origin-when-cross-origin
#   X-Frame-Options         DENY (browsers without CSP 2)
#   Content-Security-Policy frame-ancestors 'none' (the API is JSON: it must never be embedded; a stricter CSP would break
#                           Swagger UI, which serves inline scripts in development, test and staging)
#   Permissions-Policy      no camera, microphone, geolocation or payments
#   Strict-Transport-Security only with `hsts: true` (production and staging, which serve HTTPS)
#
# The panel's CSP (the one that matters for XSS) is sent by the proxy.
class SecurityHeaders
  HEADERS = {
    "X-Content-Type-Options" => "nosniff",
    "Referrer-Policy" => "strict-origin-when-cross-origin",
    "X-Frame-Options" => "DENY",
    "Content-Security-Policy" => "frame-ancestors 'none'",
    "Permissions-Policy" => "camera=(), microphone=(), geolocation=(), payment=(), usb=()"
  }.freeze
  HSTS = "max-age=63072000; includeSubDomains; preload".freeze

  def initialize(app, hsts: false)
    @app = app
    @headers = hsts ? HEADERS.merge("Strict-Transport-Security" => HSTS) : HEADERS
  end

  def call(env)
    status, headers, body = @app.call(env)
    @headers.each { |name, value| headers[name] = value }
    [ status, headers, body ]
  end
end
